import albumsData from '../../../catalog/albums.json'
import speciesData from '../../../catalog/species.json'

/** An album as generated by catalog/scripts/build_catalog.py (catalog/albums.json). */
export interface Album {
  id: string
  name: string
  description: string
  order: number
  speciesCount: number
  rareSpeciesId: string
}

export type Rarity = 'common' | 'uncommon' | 'rare' | 'legendary'

/**
 * A species as generated in catalog/species.json (schema: catalog/schema/species.schema.json).
 * Only the fields the app reads are typed here.
 */
export interface Species {
  id: string
  /** Position inside its album, from 1; null for the secret legendary species. */
  number: number | null
  albumId: string | null
  scientificName: string
  taxonLevel: 'species' | 'genus' | 'group'
  commonNameIt: string
  family: string
  rarity: Rarity
  dominantColors: string[]
  phenology: 'flowering' | 'fruiting'
  bloomMonths: number[]
  habitat: string
  altitude: string
  regions: string
  sizeNote: string
  description: string
  funFact: string
  cultivated: boolean
  /** true: legally protected; null: possibly protected in some regions (to verify). */
  protected: boolean | null
  protectionNote: string
  toxic: boolean
  toxicNote: string
  /** Catalogue ids of species that look alike. */
  lookalikes: string[]
  textStatus: string
}

export const albums: readonly Album[] = [...(albumsData as Album[])].sort((a, b) => a.order - b.order)

export const species: readonly Species[] = speciesData as Species[]

const albumIndex = new Map(albums.map((album) => [album.id, album]))
const speciesIndex = new Map(species.map((entry) => [entry.id, entry]))

export function albumById(id: string | null): Album | undefined {
  return id === null ? undefined : albumIndex.get(id)
}

export function speciesById(id: string): Species | undefined {
  return speciesIndex.get(id)
}

/** Species to collect across the albums; the secret legendary card is not part of any album. */
export const totalSpecies = albums.reduce((sum, album) => sum + album.speciesCount, 0)
